from ortools.sat.python import cp_model
import json

def main():
    N = [0, 1, 2, 3, 4, 5, 6]
    E = [(1, 2), (2, 5), (5, 0), (0, 3), (3, 4), (4, 6), (6, 0), (0, 1)]

    length = {
        (1, 2): 5.39,
        (2, 5): 7.62,
        (5, 0): 3.61,
        (0, 3): 7.21,
        (3, 4): 5.83,
        (4, 6): 2.83,
        (6, 0): 7.07,
        (0, 1): 8.0
    }

    clean_time = {
        (1, 2): 15.0,
        (2, 5): 20.0,
        (5, 0): 12.0,
        (0, 3): 18.0,
        (3, 4): 16.0,
        (4, 6): 10.0,
        (6, 0): 19.0,
        (0, 1): 22.0
    }

    model = cp_model.CpModel()

    x = {}
    y = {}

    for (i, j) in E:
        x[(i, j)] = model.NewIntVar(0, 10, f"x_{i}_{j}")

        y[(i, j)] = model.NewBoolVar(f"y_{i}_{j}")

    for (i, j) in E:
        model.Add(y[(i, j)] == 1)

    for (i, j) in E:
        model.Add(x[(i, j)] >= y[(i, j)])

    for node in N:
        incident_edges = []
        for (i, j) in E:
            if i == node or j == node:
                incident_edges.append(x[(i, j)])

        sum_var = model.NewIntVar(0, 100, f"sum_{node}")
        model.Add(sum_var == sum(incident_edges))

        k = model.NewIntVar(0, 50, f"k_{node}")
        model.Add(sum_var == 2 * k)

    subsets = []
    n = len(N)

    for mask in range(1, (1 << n) - 1):
        subset = []
        for i in range(n):
            if mask & (1 << i):
                subset.append(N[i])
        subsets.append(subset)

    for subset in subsets:
        complement = [node for node in N if node not in subset]

        cut_edges = []
        for (i, j) in E:
            if (i in subset and j in complement) or (j in subset and i in complement):
                cut_edges.append(x[(i, j)])

        if cut_edges:
            model.Add(sum(cut_edges) >= 2)

    objective_terms = []
    for (i, j) in E:
        scaled_length = int(round(length[(i, j)] * 100))
        length_expr = x[(i, j)] * scaled_length

        scaled_time = int(round(clean_time[(i, j)] * 100))
        time_expr = y[(i, j)] * scaled_time

        objective_terms.append(length_expr)
        objective_terms.append(time_expr)

    model.Minimize(sum(objective_terms))

    solver = cp_model.CpSolver()
    solver.parameters.max_time_in_seconds = 30.0
    solver.parameters.num_search_workers = 0
    solver.parameters.log_search_progress = False

    status = solver.Solve(model)

    if status in (cp_model.OPTIMAL, cp_model.FEASIBLE):
        traversal_counts = {}
        for (i, j) in E:
            traversal_counts[(i, j)] = solver.Value(x[(i, j)])

        adj = {node: [] for node in N}
        for (i, j) in E:
            count = traversal_counts[(i, j)]
            for _ in range(count):
                adj[i].append(j)
                adj[j].append(i)

        route = []
        stack = [0]

        adj_copy = {node: adj[node][:] for node in N}

        while stack:
            node = stack[-1]
            if adj_copy[node]:
                next_node = adj_copy[node].pop()
                for idx in range(len(adj_copy[next_node]) - 1, -1, -1):
                    if adj_copy[next_node][idx] == node:
                        adj_copy[next_node].pop(idx)
                        break
                stack.append(next_node)
            else:
                route.append(stack.pop())

        route = route[::-1]

        total_cost = 0
        for (i, j) in E:
            x_val = solver.Value(x[(i, j)])
            y_val = solver.Value(y[(i, j)])
            total_cost += length[(i, j)] * x_val + clean_time[(i, j)] * y_val

        print(json.dumps({
            "route": route,
            "total_cost": round(total_cost, 2)
        }))

    else:
        print(json.dumps({
            "route": [],
            "total_cost": None
        }))

if __name__ == "__main__":
    main()
